-- Allen Scripts independent hunger, thirst and energy controllers.
return function(source)
 source=source:gsub("\r\n","\n")
 if source:find("AutoThirst = false",1,true)then return source end
 local edits={
  {"AutoFood = false, AutoBuyFood = false, FoodLow = 35, FoodTarget = 80,","AutoFood = false, AutoThirst = false, AutoEnergy = false, AutoBuyFood = false, FoodLow = 35, FoodTarget = 80,\n        ThirstLow = 35, ThirstTarget = 80, EnergyLow = 30, EnergyTarget = 80,"},
  {"FoodLow = {5,80}, FoodTarget = {20,100},","FoodLow = {5,80}, FoodTarget = {20,100}, ThirstLow = {5,80}, ThirstTarget = {20,100}, EnergyLow = {5,80}, EnergyTarget = {20,100},"},
  {"        if result.FoodLow >= result.FoodTarget then return nil, \"Food target must exceed the hunger threshold\" end","        if result.FoodLow >= result.FoodTarget then return nil, \"Food target must exceed the hunger threshold\" end\n        if result.ThirstLow >= result.ThirstTarget then return nil, \"Thirst target must exceed its threshold\" end\n        if result.EnergyLow >= result.EnergyTarget then return nil, \"Energy target must exceed its threshold\" end"},
  {"((tonumber(food.Hunger) or 0)>0 or (tonumber(food.Energy) or 0)>0)","((tonumber(food.Hunger) or 0)>0 or (tonumber(food.Energy) or 0)>0 or (tonumber(food.Thirst) or 0)>0)"},
